import re

class ParseError(Exception): pass

_num = r'[-+]?\d+(?:\.\d+)?'
_vec = re.compile(r'\(\s*(' + _num + r'(?:\s*,\s*' + _num + r')*)\s*\)')
_hdr = re.compile(r'\{\s*T<=(' + _num + r')\s*,\s*R<=(' + _num + r')\s*,\s*w=\('
                  r'(' + _num + r'(?:\s*,\s*' + _num + r')*)\)\s*\}')
_ann_t = re.compile(r'\[\s*t<=(' + _num + r')\s*\]')
_ann_r = re.compile(r'\[\s*r<=(' + _num + r')\s*\]')
_ann_a = re.compile(r'\[\s*α\s*=\s*(' + _num + r')\s*\]')
_label_tag = re.compile(r'([A-Za-z_]\w*)(?::([A-Za-z_]\w*))?')

def _floats(csv: str):
    return [float(x) for x in re.split(r'\s*,\s*', csv.strip()) if x]

def parse_line(s: str):
    s = s.strip()
    if not s or s.startswith('#'): return None
    # header
    m = _hdr.fullmatch(s)
    if m:
        T, R = float(m.group(1)), float(m.group(2))
        w = _floats(m.group(3))
        return {"type":"header","T":T,"R":R,"w":w}
    # aim
    if s.startswith('aim '):
        opts = [t for t in s[4:].split('/') if t]
        return {"type":"aim","list":opts}
    # scan/probe
    for verb, ann_re in (("scan", _ann_t), ("probe", _ann_r)):
        if s.startswith(verb+' '):
            tail = s[len(verb)+1:].strip()
            ann = {}
            m = ann_re.search(tail)
            if m:
                key = "t" if verb=="scan" else "r"
                ann[key] = float(m.group(1))
                tail = tail.replace(m.group(0), '').strip()
            # Target [-> x[:Tag]]
            # split "->"
            if '->' in tail:
                target, right = tail.split('->',1)
                target = target.strip()
                m2 = _label_tag.fullmatch(right.strip())
                if not m2: raise ParseError(f"bad bind: {s}")
                label, tag = m2.group(1), m2.group(2)
            else:
                parts = tail.split()
                target = parts[0]; label = parts[0]; tag=None
            return {"type":verb,"target":target,"label":label,"tag":tag,"ann":ann}
    # update: x! [α=a] with (v1,...,vk) OR x! [α=a] u=v1,...,vk
    if '!' in s:
        left, right = s.split('!',1)
        label = left.strip()
        alpha = None
        m = _ann_a.search(right)
        if m:
            alpha = float(m.group(1))
            right = right.replace(m.group(0),'').strip()
        if 'with' in right:
            vecpart = right.split('with',1)[1].strip()
        elif 'u=' in right:
            vecpart = right.split('u=',1)[1].strip()
        else:
            raise ParseError(f"missing u in update: {s}")
        mv = _vec.fullmatch(vecpart)
        if mv:
            u = _floats(mv.group(1))
        else:
            u = _floats(vecpart)
        ann = ({"α":alpha} if alpha is not None else {})
        return {"type":"update","label":label,"u":u,"ann":ann}
    - hedge $x1/$x2/.../$xm
    if s.startswith('hedge '):
        parts = [p.strip() for p in s[6:].split('/') if p.strip()]
        labels = []
        for p in parts:
            if not p.startswith('$'): raise ParseError(f"expected $label in hedge: {s}")
            labels.append(p[1:])
        return {"type":"hedge","labels":labels}
    # fallback
    if s.startswith('fallback '):
        arg = s[len('fallback '):].strip()
        if arg == 'Stop': return {"type":"fallback","mode":"Stop"}
        if arg.startswith('$'): return {"type":"fallback","mode":"Label","label":arg[1:]}
        return {"type":"fallback","mode":"Option","opt":arg}
    # commit
    if s.startswith('commit '):
        arg = s[len('commit '):].strip()
        if arg == '$fallback': return {"type":"commit","mode":"$fallback"}
        if arg.startswith('$'): return {"type":"commit","mode":"$x","label":arg[1:]}
        return {"type":"commit","mode":"Option","opt":arg}
    raise ParseError(f"cannot parse: {s}")

def run_script(lines: List[str], st: State, prod: Producer, runner: Runner=None):
    for idx, raw in enumerate(lines, 1):
        try:
            act = parse_line(raw)
            if act is None: continue
            uOut = None
            # stopOnCommit support
            if st.Committed and st.stopOnCommit: 
                if runner: runner.log({"noop":"post-commit"}, None)
                break
            t = act["type"]
            if t=="header": act_header(st, act["T"], act["R"], act["w"])
            elif t=="aim": act_aim(st, act["list"])
            elif t=="scan":
                act_scan(st, prod, act["target"], act["label"], act["tag"], act["ann"]); uOut = st.Env[act["label"]][0]
            elif t=="probe":
                act_probe(st, prod, act["target"], act["label"], act["tag"], act["ann"]); uOut = st.Env[act["label"]][0]
            elif t=="update":
                act_update(st, act["label"], act["u"], act["ann"]); uOut = st.Env[act["label"]][0]
            elif t=="hedge": act_hedge(st, act["labels"])
            elif t=="fallback":
                if act["mode"]=="Stop": act_fallback_stop(st)
                elif act["mode"]=="Option": act_fallback_option(st, act["opt"])
                else: act_fallback_label(st, act["label"])
            elif t=="commit":
                if act["mode"]=="$fallback": act_commit_fallback(st)
                elif act["mode"]=="$x": act_commit_label(st, act["label"])
                else: act_commit_option(st, act["opt"])
            if runner: runner.log(act, uOut)
        except Exception as e:
            raise ParseError(f"line {idx}: {e}") from e

