export type Option = string;
export type Label = string;
export type Vec = number[];
export type RecordT = { u: Vec; tag?: Option };
export type Weights = Vec;

export interface Config {
  strictHedge?: boolean;
  stopOnCommit?: boolean;
  errorOnNoHeader?: boolean;
  seed?: number;
}

export interface State {
  k: number; T: number; R: number;
  w: Weights; Aim: Option[];
  rankMap: Map<Option, number>;
  Env: Map<Label, RecordT>;
  Fallback?: "Stop" | Option;
  Winner?: Label;
  Committed: boolean;
  Action?: Option | "Stop" | Label;
  rng: () => number;  // pluggable PRNG
  cfg: Required<Config>;
}

export interface Producer {
  observe(verb: "scan"|"probe",
          target: string,
          ann: Record<string, number>,
          stateRO: Readonly<{
            k:number; T:number; R:number; w:Weights; Aim:Option[];
            Env: Record<string, RecordT>; seed:number;
          }>): Vec;
}

export function dot(a: Vec, b: Vec): number { return a.reduce((s,x,i)=>s+x*b[i],0); }
export function clamp01(v: Vec): Vec { return v.map(x=>x<0?0:x>1?1:x); }

export class DeterministicStub implements Producer {
  constructor(private seed:number=42){}
  private stableInt(s:string): number {
    // simple FNV-1a 64-bit
    let hBig = 1469598103934665603n;
    for (const ch of Buffer.from(s)) { hBig ^= BigInt(ch); hBig *= 1099511628211n; }
    return Number(hBig & ((1n<<53n)-1n)); // keep 53 bits
  }
  observe(verb, target, ann, stateRO): Vec {
    const h = this.stableInt(`${verb}:${target}:${stateRO.T.toFixed(3)}:${stateRO.R.toFixed(3)}`);
    let seed = (stateRO.seed ^ h) >>> 0;
    // LCG
    const lcg = ()=> (seed = (1664525*seed + 1013904223)>>>0, seed/2**32);
    const k = stateRO.k;
    return Array.from({length:k}, ()=> lcg());
  }
}

