TypeScript evaluator (single-file, compact)
Note: Mirrors your Python semantics: budgets, Aim/rankMap, N-ary hedge with strictHedge, idempotent commit, stopOnCommit.

type Option = string;
type Label = string;
type Vec = number[];
type RecordT = { u: Vec; tag?: Option };

type Config = {
  strictHedge?: boolean;
  stopOnCommit?: boolean;
  errorOnNoHeader?: boolean;
  seed?: number;
};

type State = {
  k: number; T: number; R: number;
  w: Vec; Aim: Option[]; rankMap: Map<Option, number>;
  Env: Map<Label, RecordT>;
  Fallback?: "Stop" | Option;
  Winner?: Label;
  Committed: boolean;
  Action?: Option | "Stop" | Label;
  cfg: Required<Config>;
};

const EPS = 1e-9;
const INF = 1e9;

function nearEq(a: number, b: number, eps=EPS){ return Math.abs(a-b)<=eps; }
function dot(a: Vec, b: Vec){ return a.reduce((s,x,i)=>s+x*b[i],0); }
function clamp01(v: Vec){ return v.map(x=>x<0?0:x>1?1:x); }

function initState(T: number, R: number, w: Vec, Aim: Option[], k: number, cfg: Config): State {
  if (k!==w.length) throw new Error("k != len(w)");
  if (!nearEq(w.reduce((s,x)=>s+x,0),1)) throw new Error("w must sum to 1");
  if (w.some(x=>x< -EPS)) throw new Error("w nonnegative");
  const fullCfg: Required<Config> = {
    strictHedge: cfg.strictHedge ?? false,
    stopOnCommit: cfg.stopOnCommit ?? false,
    errorOnNoHeader: cfg.errorOnNoHeader ?? false,
    seed: cfg.seed ?? 42
  };
  const rankMap = new Map<Option,number>(Aim.map((o,i)=>[o,i]));
  return { k, T, R, w: w.slice(), Aim: Aim.slice(), rankMap,
           Env: new Map(), Committed:false, cfg: fullCfg };
}

function aim(st: State, list: Option[]){
  st.Aim = list.slice();
  st.rankMap = new Map(list.map((o,i)=>[o,i]));
}

function scan(st: State, producer: (verb:"scan"|"probe", target:string, ann: any, stRO:any)=>Vec,
              target: string, label: Label, tag?: Option, ann: any = {}) {
  if (st.Committed && st.cfg.stopOnCommit) return;
  const dt = ann.t ?? 1.0;
  if (st.T - dt < -EPS) throw new Error("T underflow");
  st.T -= dt;
  const u = producer("scan", target, ann, {k:st.k,T:st.T,R:st.R,w:st.w,Aim:st.Aim,seed:st.cfg.seed,Env:{}}); // Env omitted for simplicity
  if (u.length!==st.k) throw new Error("k mismatch");
  st.Env.set(label, { u: clamp01(u), tag });
}

function probe(st: State, producer: (verb:"scan"|"probe", target:string, ann: any, stRO:any)=>Vec,
               target: string, label: Label, tag?: Option, ann: any = {}) {
  if (st.Committed && st.cfg.stopOnCommit) return;
  const dr = ann.r ?? 1.0;
  if (st.R - dr < -EPS) throw new Error("R underflow");
  st.R -= dr;
  const u = producer("probe", target, ann, {k:st.k,T:st.T,R:st.R,w:st.w,Aim:st.Aim,seed:st.cfg.seed,Env:{}}); // Env omitted for simplicity
  if (u.length!==st.k) throw new Error("k mismatch");
  st.Env.set(label, { u: clamp01(u), tag });
}

function update(st: State, label: Label, uPrime: Vec, alpha=0.5){
  if (st.Committed && st.cfg.stopOnCommit) return;
  const rec = st.Env.get(label); if (!rec) throw new Error("missing label");
  if (uPrime.length!==st.k) throw new Error("k mismatch");
  const u = rec.u;
  const newu = u.map((a,i)=> (1-alpha)*a + alpha*uPrime[i]);
  st.Env.set(label, { u: clamp01(newu), tag: rec.tag });
  if (st.Winner===label) st.Winner = undefined; // optional auto-clear
}

function hedge(st: State, labels: Label[]){
  if (st.Committed && st.cfg.stopOnCommit) return;
  const missing = labels.filter(l=>!st.Env.has(l));
  if (st.cfg.strictHedge && missing.length) throw new Error("strict hedge: "+missing.join(","));
  const L = labels.filter(l=>st.Env.has(l));
  if (L.length===0) return;
  let best = L[0];
  let bestS = dot(st.w, st.Env.get(best)!.u);
  for (let i=1;i<L.length;i++){
    const xi = L[i], si = dot(st.w, st.Env.get(xi)!.u);
    if (si > bestS + EPS) { best = xi; bestS = si; }
    else if (nearEq(si,bestS)){
      const ta = st.Env.get(best)!.tag, tb = st.Env.get(xi)!.tag;
      const ra = ta!==undefined ? (st.rankMap.get(ta) ?? INF) : INF;
      const rb = tb!==undefined ? (st.rankMap.get(tb) ?? INF) : INF;
      if (rb < ra || (rb===ra && i < L.indexOf(best))) { best = xi; bestS = si; }
    }
  }
  st.Winner = best;
}

function fallbackStop(st: State){ st.Fallback = "Stop"; }
function fallbackOption(st: State, opt: Option){ st.Fallback = opt; }
function fallbackLabel(st: State, x: Label){
  const rec = st.Env.get(x);
  if (rec?.tag!==undefined) st.Fallback = rec.tag;
}

function commitFallback(st: State){
  if (st.Committed) return;
  if (st.Fallback==="Stop"){ st.Action="Stop"; st.Committed=true; }
  else if (typeof st.Fallback==="string"){ st.Action=st.Fallback; st.Committed=true; }
}

function commitLabel(st: State, x: Label){
  if (st.Committed) return;
  const rec = st.Env.get(x); if (!rec) return;
  st.Action = rec.tag ?? x;
  st.Committed = true;
}

function commitOption(st: State, opt: Option){
  if (st.Committed) return;
  st.Action = opt; st.Committed = true;
}

/* Producers (compact, deterministic) */
function fnv1a53(s: string): number {
  let h = 0xCBF29CE484222325n;
  for (const b of Buffer.from(s)) { h ^= BigInt(b); h = (h * 0x100000001B3n) & ((1n<<64n)-1n); }
  const v = Number(h & ((1n<<53n)-1n));
  return v >>> 0;
}
function makeDeterministicStub(seed:number){
  return (verb:"scan"|"probe", target:string, ann:any, ro:any): Vec => {
    let s = (ro.seed ^ fnv1a53(`${verb}:${target}:${ro.T.toFixed(3)}:${ro.R.toFixed(3)}`)) >>> 0;
    const lcg = ()=> (s = (1664525*s + 1013904223)>>>0, s/2**32);
    return Array.from({length:ro.k}, ()=> lcg());
  };
}
function makeSeededStochastic(seed:number){
  return (verb:"scan"|"probe", target:string, ann:any, ro:any): Vec => {
    let s = (ro.seed ^ fnv1a53(`${verb}:${target}`)) >>> 0;
    const lcg = ()=> (s = (1664525*s + 1013904223)>>>0, s/2**32);
    const k = ro.k, T=ro.T, R=ro.R;
    const tScale = 1 + Math.max(0, 1 - T/(1+T));
    const rScale = 1 + Math.max(0, 1 - R/(1+R));
    const beta = (a:number,b:number)=> {
      // Marsaglia polar-ish Beta via Gamma (shape>0): quick-and-dirty
      const gamma = (shape:number) => {
        // Ahrens-Dieter for shape>1, else boost
        const sh = shape<1 ? shape+1 : shape;
        while(true){
          const u = lcg(), v = lcg();
          const x = Math.pow(u, 1/sh);
          const y = Math.pow(v, 1/(1));
          if (x + y <= 1){
            const g = -Math.log(lcg()) * x / (x + y);
            return shape<1 ? g * Math.pow(lcg(), 1/shape) : g;
          }
        }
      };
      const ga = gamma(a), gb = gamma(b);
      return ga/(ga+gb);
    };
    const out: number[] = [];
    for (let i=0;i<k;i++){
      const a = 2*(i%2===0 ? tScale : 1), b = 2*(i%2===1 ? rScale : 1);
      out.push(beta(a,b));
    }
    return out;
  };
}

/* Tests (minimal) */
function assert(cond: any, msg: string){ if(!cond) throw new Error("Assert: "+msg); }

function testIdempotentCommit(){
  const st = initState(2,2,[1.0],["A"],1,{seed:1});
  const prod = makeDeterministicStub(st.cfg.seed);
  scan(st, prod, "A", "a", "A");
  hedge(st, ["a"]);
  commitLabel(st, st.Winner!);
  const a1 = st.Action, c1 = st.Committed;
  commitOption(st, "B");
  commitFallback(st);
  assert(st.Action===a1 && st.Committed===c1, "commit idempotency failed");
  return "ok";
}

function testStochasticRepro(){
  const run = (seed:number)=>{
    const st = initState(2,2,[0.5,0.5],["N","S"],2,{seed});
    const prod = makeSeededStochastic(st.cfg.seed);
    scan(st, prod, "N","n","N");
    probe(st, prod, "S","s","S");
    const un = st.Env.get("n")!.u.slice(), us = st.Env.get("s")!.u.slice();
    hedge(st, ["n","s"]); commitLabel(st, st.Winner!);
    return {un, us, act: st.Action};
  };
  const a = run(10), b = run(10), c = run(11);
  const same = JSON.stringify(a)===JSON.stringify(b);
  const diff = JSON.stringify(a)!==JSON.stringify(c);
  assert(same && diff, "stochastic reproducibility failed");
  return "ok";
}

