2) Minimal Python CLI (eval_plan.py)
Assumes you have: init_state, Config, Runner, run_script, DeterministicStub, SeededStochastic, round_floats on import path.

#!/usr/bin/env python3
import argparse, json, sys, hashlib
from pathlib import Path

# import your evaluator bits
from your_module import (
    init_state, Config, Runner, run_script,
    DeterministicStub, SeededStochastic, round_floats
)

def stable_hash(obj):
    blob = json.dumps(round_floats(obj), sort_keys=True, separators=(",",":"))
    return hashlib.sha256(blob.encode()).hexdigest()

def main():
    ap = argparse.ArgumentParser(description="Evaluate micro-language plan")
    ap.add_argument("plan", type=Path, help="plan.txt")
    ap.add_argument("--seed", type=int, default=42)
    ap.add_argument("--strict-hedge", action="store_true")
    ap.add_argument("--stop-on-commit", action="store_true")
    ap.add_argument("--error-on-no-header", action="store_true")
    ap.add_argument("--producer", choices=["deterministic","stochastic"], default="deterministic")
    ap.add_argument("--json", type=Path, help="write trace JSON to file")
    ap.add_argument("--hash", action="store_true", help="print transcript hash")
    # minimal required header to init state (can be overridden by script header)
    ap.add_argument("--k", type=int, default=2)
    ap.add_argument("--T", type=float, default=0.0)
    ap.add_argument("--R", type=float, default=0.0)
    ap.add_argument("--w", type=str, default="", help="comma-separated weights; if empty, infer from --k as uniform")
    ap.add_argument("--aim", type=str, default="", help="slash-separated Aim, e.g. N/S/E")
    args = ap.parse_args()

    if args.w:
        w = [float(x) for x in args.w.split(",")]
        k = len(w)
    else:
        k = args.k
        w = [1.0/k]*k
    Aim = [o for o in args.aim.split("/") if o] if args.aim else []

    cfg = Config(seed=args.seed, strictHedge=args.strict_hedge,
                 stopOnCommit=args.stop_on_commit, errorOnNoHeader=args.error_on_no_header)
    st = init_state(T=args.T, R=args.R, w=w, Aim=Aim, k=k, cfg=cfg)
    prod = DeterministicStub() if args.producer=="deterministic" else SeededStochastic()
    runner = Runner(st, prod)

    lines = args.plan.read_text().splitlines()
    run_script(lines, st, prod, runner)

    meta = {
        "k": st.k, "seed": cfg.seed, "strictHedge": cfg.strictHedge,
        "stopOnCommit": cfg.stopOnCommit, "errorOnNoHeader": cfg.errorOnNoHeader,
        "w": st.w, "Aim": st.Aim
    }
    transcript = {"meta": meta, "steps": runner.trace}
    transcript["hash"] = stable_hash({"meta": meta, "steps": runner.trace})

    if args.json:
        args.json.write_text(json.dumps(transcript, sort_keys=True, separators=(",",":")))
    final = st.Action
    if args.hash:
        print(transcript["hash"], final)
    else:
        print(final)

if __name__ == "__main__":
    sys.exit(main())

