describe("commit idempotency", () => {
  it("keeps Action after first commit", () => {
    const st = initState(2,2,[1.0],["A"],1,{seed:1});
    const prod = makeDeterministicStub(st.cfg.seed);
    scan(st, prod, "A", "a", "A");
    hedge(st, ["a"]);
    commitLabel(st, st.Winner!);
    const a1 = st.Action, c1 = st.Committed;
    commitOption(st, "B");
    commitFallback(st);
    expect(st.Action).toBe(a1);
    expect(st.Committed).toBe(c1);
  });
});

describe("SeededStochastic reproducibility", () => {
  const run = (seed:number) => {
    const st = initState(2,2,[0.5,0.5],["N","S"],2,{seed});
    const prod = makeSeededStochastic(st.cfg.seed);
    scan(st, prod, "N","n","N");
    probe(st, prod, "S","s","S");
    const un = st.Env.get("n")!.u.slice();
    const us = st.Env.get("s")!.u.slice();
    hedge(st, ["n","s"]); commitLabel(st, st.Winner!);
    return {un, us, act: st.Action};
  };
  it("same seed -> same; different seed -> different", () => {
    const a = run(10), b = run(10), c = run(11);
    expect(a).toEqual(b);
    expect(a).not.toEqual(c);
  });
});

describe("strict hedge", () => {
  it("errors on missing when strictHedge=true", () => {
    const st = initState(2,2,[1.0],[],1,{seed:4, strictHedge:true});
    const prod = makeDeterministicStub(st.cfg.seed);
    scan(st, prod, "X", "a");
    expect(()=> hedge(st, ["a","missing"])).toThrow();
    st.cfg.strictHedge = false;
    expect(()=> hedge(st, ["a","missing"])).not.toThrow();
    expect(st.Winner).toBe("a");
  });
});

